"""Generated by func2vec.generate_cluster.
Intent: k=8 dataset_size=small data_kind=text structure=partition
Picked algorithm: sklearn.cluster.KMeans
Preprocessing (embedding-picked where applicable): ['sklearn.feature_extraction.text.TfidfVectorizer']
Evaluation (embedding-ranked): ['sklearn.metrics.homogeneity_score', 'sklearn.metrics.silhouette_score', 'sklearn.metrics.completeness_score']
"""

import numpy as np
from sklearn.datasets import fetch_20newsgroups
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.cluster import KMeans
from sklearn.metrics import homogeneity_score
from sklearn.metrics import silhouette_score
from sklearn.metrics import completeness_score


def load_data():
    ds = fetch_20newsgroups(subset='train', remove=('headers','footers','quotes'))
    return ds.data, ds.target


def build_pipeline():
    steps = []
    steps.append(TfidfVectorizer(max_features=5000, stop_words='english'))
    steps.append(KMeans(random_state=42, n_clusters=8))
    return steps


def run(X, y=None):
    steps = build_pipeline()
    Xt = X
    for step in steps[:-1]:
        Xt = step.fit_transform(Xt)
    clusterer = steps[-1]
    if hasattr(clusterer, 'fit_predict'):
        labels = clusterer.fit_predict(Xt)
    else:
        clusterer.fit(Xt)
        labels = clusterer.labels_

    scoreable = labels[labels != -1] if -1 in np.unique(labels) else labels
    Xs = Xt[labels != -1] if -1 in np.unique(labels) else Xt
    n_clusters = len(set(scoreable))
    print(f'algorithm    : {clusterer.__class__.__name__}')
    print(f'n_clusters   : {n_clusters}')
    if n_clusters >= 2:
        if y is not None:
            print(f'homogeneity_score       : {homogeneity_score(y, labels):.4f}')
        print(f'silhouette_score        : {silhouette_score(Xs, scoreable):.4f}')
        if y is not None:
            print(f'completeness_score      : {completeness_score(y, labels):.4f}')
    else:
        print('too few clusters formed to score')
    return labels


if __name__ == '__main__':
    X, y = load_data()
    # Text pipeline: the vectorizer converts strings to a matrix.
    run(X, y)
